package com.campus.remarket;
import java.net.*;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.springframework.jdbc.core.JdbcTemplate;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"spring.datasource.url=jdbc:h2:mem:admincampustests;MODE=MySQL;DB_CLOSE_DELAY=-1","campus.notifications.initial-delay-ms=3600000","campus.mail.mock=true"})
class AdminCampusIntegrationTests {
 @LocalServerPort int port;@Autowired JdbcTemplate db;final JsonMapper json=JsonMapper.builder().build();final AtomicInteger serial=new AtomicInteger(1);
 HttpClient browser(){return HttpClient.newBuilder().cookieHandler(new CookieManager()).build();}
 HttpResponse<String> send(HttpClient c,String method,String path,Object body,String token)throws Exception{var b=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+path));SecurityTestClient.csrf(c,b,method,path,port);if(body!=null)b.header("Content-Type","application/json");if(token!=null)b.header("X-CSRF-Token",token);return c.send(b.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body))).build(),HttpResponse.BodyHandlers.ofString());}
 JsonNode call(HttpClient c,String method,String path,Object body,String token,int expected)throws Exception{var r=send(c,method,path,body,token);assertEquals(expected,r.statusCode(),r.body());return r.body().isBlank()?null:json.readTree(r.body());}
 JsonNode school(HttpClient c,String name)throws Exception{for(var s:call(c,"GET","/api/members/schools",null,null,200))if(s.get("name").asText().equals(name))return s;throw new AssertionError(name);}
 void login(HttpClient c,Long school,String id,String password)throws Exception{var data=new LinkedHashMap<String,Object>();data.put("schoolId",school);data.put("loginId",id);data.put("password",password);call(c,"POST","/api/members/login",data,null,200);}
 HttpClient admin()throws Exception{var c=browser();login(c,null,"admin1","campus1234!");return c;}
 String token(HttpClient c)throws Exception{return call(c,"GET","/api/boards/session",null,null,200).get("csrfToken").asText();}
 HttpClient signup(String name,String student)throws Exception{var c=browser();var s=school(c,name);String email=student+"@"+s.get("emailDomain").asText().split(",")[0];var data=Map.of("schoolId",s.get("id").asLong(),"email",email);String code=call(c,"POST","/api/members/email/code",data,null,200).get("devCode").asText();call(c,"POST","/api/members/email/verify",Map.of("email",email,"code",code),null,200);call(c,"POST","/api/members/signup",Map.of("schoolId",s.get("id").asLong(),"studentNo",student,"password","campus1234!","name","학교분리학생","email",email,"phone","010-1111-2222","studentStatus","ENROLLED"),null,201);login(c,s.get("id").asLong(),student,"campus1234!");return c;}
 boolean contains(JsonNode a,String field,long id){for(var item:a)if(item.get(field).asLong()==id)return true;return false;}
 @Test void threeCampusesSignupSameStudentIdAndIsolateAllContentAndMap()throws Exception{
  String[] names={"인하대학교","인천대학교","청운대학교 인천캠퍼스"};var users=new ArrayList<HttpClient>();var schools=new ArrayList<Long>();var sales=new ArrayList<Long>();var posts=new ArrayList<Long>();var shops=new ArrayList<Long>();
  for(int i=0;i<3;i++){var u=signup(names[i],"20269401");users.add(u);long school=school(u,names[i]).get("id").asLong();schools.add(school);var campus=call(u,"GET","/api/campus",null,null,200);assertEquals(school,campus.get("id").asLong());assertEquals(names[i],campus.get("name").asText());assertNotNull(campus.get("latitude"));
   long sale=call(u,"POST","/api/products",Map.of("name",names[i]+" 교재","category","전공서적","oprice",10000,"detail","같은학교","location","정문","schoolId",999999),null,200).get("selno").asLong();sales.add(sale);
   long post=call(u,"POST","/api/boards",Map.of("categoryId",6,"title",names[i]+" 맛집","content","학교생활 이야기","schoolId",999999),token(u),200).get("postId").asLong();posts.add(post);
   db.update("INSERT INTO shops(school_id,shopname,busi_kind,checked,status,latitude,longitude) VALUES(?,?,'카페',TRUE,'영업중',?,?)",school,names[i]+" 테스트 가게",campus.get("latitude").decimalValue(),campus.get("longitude").decimalValue());shops.add(db.queryForObject("SELECT shopId FROM shops WHERE shopname=?",Long.class,names[i]+" 테스트 가게"));
   assertEquals(school,db.queryForObject("SELECT school_id FROM sales WHERE selno=?",Long.class,sale));assertEquals(school,db.queryForObject("SELECT school_id FROM board_posts WHERE post_id=?",Long.class,post));
  }
  for(int i=0;i<3;i++){var u=users.get(i);assertEquals(3,call(u,"GET","/api/members/schools",null,null,200).size());var saleList=call(u,"GET","/api/products?schoolId="+schools.get((i+1)%3),null,null,200);var boardList=call(u,"GET","/api/boards",null,null,200);var shopList=call(u,"GET","/api/shops",null,null,200);
   for(int j=0;j<3;j++){assertEquals(i==j,contains(saleList,"selno",sales.get(j)));assertEquals(i==j,contains(boardList,"postId",posts.get(j)));assertEquals(i==j,contains(shopList,"id",shops.get(j)));if(i!=j){call(u,"GET","/api/products/"+sales.get(j),null,null,404);call(u,"GET","/api/products/"+sales.get(j)+"/seller-profile",null,null,404);call(u,"GET","/api/boards/"+posts.get(j),null,null,404);call(u,"GET","/api/boards/"+posts.get(j)+"/comments",null,null,404);call(u,"POST","/api/boards/"+posts.get(j)+"/comments",Map.of("content","교차 댓글"),token(u),404);call(u,"POST","/api/trades",Map.of("selno",sales.get(j)),null,404);String target="SALE:"+sales.get(j);assertFalse(call(u,"GET","/api/engagement/state?targets="+target,null,null,200).get(0).get("available").asBoolean());}}
  }
  assertNotEquals(call(users.get(0),"GET","/api/campus",null,null,200).get("latitude"),call(users.get(1),"GET","/api/campus",null,null,200).get("latitude"));
  var switched=users.get(0);call(switched,"POST","/api/members/logout",null,null,200);login(switched,schools.get(1),"20269401","campus1234!");assertEquals(names[1],call(switched,"GET","/api/campus",null,null,200).get("name").asText());assertFalse(contains(call(switched,"GET","/api/products",null,null,200),"selno",sales.get(0)));
 }
 @Test void nonInhaTradeRetainsOwnershipNotificationsAndCompletion()throws Exception{
  for(String name:List.of("인천대학교","청운대학교 인천캠퍼스")){var seller=signup(name,"20269411");var buyer=signup(name,"20269412");var s=call(seller,"POST","/api/products",Map.of("name","학교별 거래 확인","category","전공서적","oprice",7000,"detail","검증","location","정문"),null,200);assertTrue(s.get("seller").asText().startsWith("member:"));var order=call(buyer,"POST","/api/trades",Map.of("selno",s.get("selno").asLong()),null,200);String id=order.get("orderId").asText();assertEquals(1,call(seller,"GET","/api/notifications",null,null,200).size());assertEquals(1,call(buyer,"GET","/api/notifications",null,null,200).size());call(seller,"POST","/api/trades/"+id+"/complete",null,null,200);var rating=call(buyer,"GET","/api/trades/"+id+"/rating",null,null,200);assertTrue(rating.get("rating").get("canRate").asBoolean());}
 }
 @Test void schoolImageUploadIsAdminOnlyAndUsesRealImageBytes()throws Exception{
  var a=admin();String csrf=call(a,"GET","/api/admin/dashboard",null,null,200).get("csrfToken").asText();var buffer=new java.io.ByteArrayOutputStream();javax.imageio.ImageIO.write(new java.awt.image.BufferedImage(12,12,java.awt.image.BufferedImage.TYPE_INT_RGB),"png",buffer);byte[] png=buffer.toByteArray();String boundary="campusimage";var bytes=new java.io.ByteArrayOutputStream();bytes.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\"file\"; filename=\"campus.png\"\r\nContent-Type: image/png\r\n\r\n").getBytes(StandardCharsets.UTF_8));bytes.write(png);bytes.write(("\r\n--"+boundary+"--\r\n").getBytes(StandardCharsets.UTF_8));
  var request=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/admin/catalog/images")).header("Content-Type","multipart/form-data; boundary="+boundary).header("X-CSRF-Token",csrf).POST(HttpRequest.BodyPublishers.ofByteArray(bytes.toByteArray())).build();var response=a.send(request,HttpResponse.BodyHandlers.ofString());assertEquals(200,response.statusCode(),response.body());String image=json.readTree(response.body()).get("name").asText();var saved=a.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/school-images/"+image)).GET().build(),HttpResponse.BodyHandlers.ofByteArray());assertEquals(200,saved.statusCode());assertArrayEquals(png,saved.body());assertEquals(401,browser().send(request,HttpResponse.BodyHandlers.ofString()).statusCode());
  var input=new LinkedHashMap<>(schoolInput("학교 이미지 테스트",0));input.put("photo",image);input.put("mapImage",image);var school=call(a,"POST","/api/admin/catalog/schools",input,csrf,200);assertEquals(image,school.get("photo").asText());assertEquals(image,school.get("mapImage").asText());call(a,"DELETE","/api/admin/catalog/schools/"+school.get("id").asLong()+"?version="+school.get("version").asLong(),null,csrf,200);
 }
 @Test void loggedInPasswordPageAndChangeRequireCurrentPasswordAndInvalidateSession()throws Exception{
  var guest=browser();assertEquals(302,send(guest,"GET","/account.html",null,null).statusCode());var u=signup("인하대학교","20269402");assertEquals(302,send(u,"GET","/account.html",null,null).statusCode());call(u,"POST","/api/account/password",Map.of("oldPassword","wrong","password","newCampus123!"),null,400);call(u,"POST","/api/account/password",Map.of("oldPassword","campus1234!","password","newCampus123!"),null,200);assertEquals(302,send(u,"GET","/account.html",null,null).statusCode());login(u,school(guest,"인하대학교").get("id").asLong(),"20269402","newCampus123!");assertEquals(302,send(u,"GET","/account.html",null,null).statusCode());
 }
 Map<String,Object> schoolInput(String name,long version){return Map.of("name",name,"region","인천","address","인천 테스트 주소","latitude",37.4,"longitude",126.6,"emailDomain","school.example.edu,alumni.example.edu","version",version);}
 @Test void adminSchoolCrudDomainValidationVersionsAndInUseDeletion()throws Exception{
  var a=admin();String csrf=call(a,"GET","/api/admin/dashboard",null,null,200).get("csrfToken").asText();call(browser(),"GET","/api/admin/catalog/schools",null,null,401);var student=signup("인하대학교","20269403");call(student,"GET","/api/admin/catalog/schools",null,null,403);call(a,"POST","/api/admin/catalog/schools",schoolInput("새 학교",0),null,403);
  var input=new LinkedHashMap<>(schoolInput("테스트 학교",0));input.put("emailDomain","person@example.edu");call(a,"POST","/api/admin/catalog/schools",input,csrf,400);
  var s=call(a,"POST","/api/admin/catalog/schools",schoolInput("테스트 학교",0),csrf,200);long id=s.get("id").asLong(),version=s.get("version").asLong();assertEquals("school.example.edu,alumni.example.edu",s.get("emailDomain").asText());call(a,"POST","/api/admin/catalog/schools",schoolInput("테스트 학교",0),csrf,409);
  call(a,"PUT","/api/admin/catalog/schools/"+id,schoolInput("변경 학교",999),csrf,409);var updated=call(a,"PUT","/api/admin/catalog/schools/"+id,schoolInput("변경 학교",version),csrf,200);call(a,"DELETE","/api/admin/catalog/schools/"+id+"?version="+updated.get("version").asLong(),null,csrf,200);
  var inha=call(a,"GET","/api/admin/catalog/schools",null,null,200);for(var school:inha)if(school.get("name").asText().equals("인하대학교"))call(a,"DELETE","/api/admin/catalog/schools/"+school.get("id").asLong()+"?version="+school.get("version").asLong(),null,csrf,409);
 }
 @Test void categoryCrudRenamesReferencesAndPreventsInUseDelete()throws Exception{
  var a=admin();String csrf=call(a,"GET","/api/admin/dashboard",null,null,200).get("csrfToken").asText();call(a,"POST","/api/admin/catalog/categories",Map.of("name","테스트 업종"),csrf,200);var categories=call(a,"GET","/api/admin/catalog/categories",null,null,200);JsonNode category=null;for(var c:categories)if(c.get("name").asText().equals("테스트 업종"))category=c;assertNotNull(category);long id=category.get("id").asLong();call(a,"POST","/api/admin/catalog/categories",Map.of("name","테스트 업종"),csrf,409);long school=school(a,"인하대학교").get("id").asLong();db.update("INSERT INTO shops(school_id,shopname,busi_kind,checked,status) VALUES(?,'업종 연결 테스트','테스트 업종',TRUE,'영업중')",school);
  call(a,"PUT","/api/admin/catalog/categories/"+id,Map.of("name","변경 업종","version",0),csrf,200);assertEquals("변경 업종",db.queryForObject("SELECT busi_kind FROM shops WHERE shopname='업종 연결 테스트'",String.class));call(a,"DELETE","/api/admin/catalog/categories/"+id+"?version=1",null,csrf,409);db.update("DELETE FROM shops WHERE shopname='업종 연결 테스트'");call(a,"DELETE","/api/admin/catalog/categories/"+id+"?version=1",null,csrf,200);for(String name:List.of("카페","편의점","중식","양식","디저트","호프","주점","당구장","탁구장")){boolean found=false;for(var c:call(a,"GET","/api/business-categories",null,null,200))if(c.get("name").asText().equals(name))found=true;assertTrue(found,name);}
 }
}
